package com.dbu.reservation.infrastructure.security;
import com.dbu.reservation.application.service.PasswordEncoder;
import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import java.security.*;import java.util.Base64;
public final class PasswordHasher implements PasswordEncoder {private final SecureRandom random=new SecureRandom();public String encode(String password){byte[] salt=new byte[16];random.nextBytes(salt);return "pbkdf2$"+Base64.getEncoder().encodeToString(salt)+"$"+Base64.getEncoder().encodeToString(derive(password.toCharArray(),salt));}public boolean matches(String password,String encoded){try{String[] p=encoded.split("\\$");return p.length==3&&MessageDigest.isEqual(derive(password.toCharArray(),Base64.getDecoder().decode(p[1])),Base64.getDecoder().decode(p[2]));}catch(RuntimeException e){return false;}}private byte[] derive(char[] p,byte[] salt){PBEKeySpec spec=new PBEKeySpec(p,salt,210000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}catch(Exception e){throw new IllegalStateException(e);}finally{spec.clearPassword();}}}
